    """Find the minimal edit that transforms s_in into s_out"""
    # Find first position where strings differ
    min_len = min(len(s_in), len(s_out))

    # Find where they first differ
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    # If no difference found in common length, check lengths
    if pos == -1:
        if len(s_in) < len(s_out):
            pos = len(s_in)
        else:
            pos = len(s_out)

    # Determine what needs to change
    if len(s_in) < len(s_out):
        # Insertion case
        old_sub = ""
        new_sub = s_out[pos]
    elif len(s_in) > len(s_out):
        # Deletion case  
        old_sub = s_in[pos]
        new_sub = ""
    else:
        # Substitution case
        old_sub = s_in[pos]
        new_sub = s_out[pos]

    return (old_sub, new_sub, pos)

