def find_minimal_edit(s_in, s_out):
    """Find minimal edit - this is tricky since we're doing replacements"""
    # For replacement operations, let's find the first position where they differ
    min_len = min(len(s_in), len(s_out))
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found a difference - check if it's substitution or insertion/deletion
            if len(s_in) == len(s_out):
                return (s_in[i], s_out[i], i)  # substitution
            elif len(s_in) < len(s_out):
                return ("", s_out[i], i)  # insertion
            else:
                return (s_in[i], "", i)   # deletion
    # If we got here, one string is prefix of other
    if len(s_in) < len(s_out):
        return ("", s_out[len(s_in)], len(s_in))  # insertion at end
    elif len(s_in) > len(s_out):
        return (s_in[len(s_out)], "", len(s_out))  # deletion at end
    return ("", "", -1)  # no difference

def propose_rule_candidates(s_in, s_out):
    """Propose candidates for replacement rules"""
    # Get the minimal edit
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    candidates = []

    # If it's a simple character substitution
    if old_sub and new_sub and len(old_sub) == 1 and len(new_sub) == 1:
        candidates.append((old_sub, new_sub))

    # If it's an insertion at the beginning
    if old_sub == "" and new_sub and pos == 0:
        candidates.append(("", new_sub))  # Insert at start

    # If it's an insertion in the middle
    if old_sub == "" and new_sub and pos > 0:
        candidates.append(("", new_sub))  # Insert at position

    # If it's a substitution of entire string
    if len(s_in) == len(s_out):
        candidates.append((s_in, s_out))

    # General case - entire string replacement
    candidates.append((s_in, s_out))

    return candidates

